  if (exact.length > 1) {
    throw new Error(
      purpose + ': duplicate ds_contracts/contractId "' + ref.contractId +
      '" on ' + exact.length + ' component targets — refusing ambiguous identity',
    );
  }
  if (exact.length === 1) return exact[0];

